def get_day_stats(date_str, label):
    try:
        start = ee.Date(date_str)
        end = start.advance(1, 'day')
        datasets = ['NOAA/VIIRS/002/VNP46A1', 'NOAA/VIIRS/001/VNP46A1']
        col = None
        chosen_ds = None
        for ds in datasets:
            tmp = ee.ImageCollection(ds).filterBounds(aoi).filterDate(start, end)
            if tmp.size().getInfo() > 0:
                col = tmp
                chosen_ds = ds
                break
        if col is None:
            print(f"{label} Images: 0")
            return {'status': 'C1'}
        size = col.size().getInfo()
        img = col.mosaic()

        bands = img.bandNames().getInfo()
        cand = [
            'DNB_BRDF-Corrected_NTL',
            'Gap_Filled_DNB_BRDF-Corrected_NTL',
            'DNB_BRDF_Corrected_NTL',
            'Gap_Filled_DNB_BRDF_Corrected_NTL'
        ]
        sel_band = next((b for b in cand if b in bands), None)
        if sel_band is None:
            print(f"{label} Band not found in {chosen_ds}.")
            return {'status': 'D'}

        band = img.select(sel_band)

        # Quality mask
        if 'Latest_High_Quality_Retrieval' in bands:
            mask = img.select('Latest_High_Quality_Retrieval').eq(1)
        elif 'QF_Cloud_Mask' in bands:
            qf = img.select('QF_Cloud_Mask')
            mask = qf.bitwiseAnd(3).lt(2)  # bits 0-1: keep <2 (clear/prob clear)
        else:
            mask = ee.Image(1)

        band = band.updateMask(mask).updateMask(band.gte(0))

        total_px = ee.Image.constant(1).rename('ones').reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=aoi,
            scale=scale,
            maxPixels=1e9
        ).get('ones').getInfo()
        valid_px = band.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=aoi,
            scale=scale,
            maxPixels=1e9
        ).get(sel_band).getInfo()

        if total_px is None or total_px == 0:
            print(f"{label} Images: {size}, Total px: 0")
            return {'status': 'C2'}
        if valid_px is None or valid_px == 0:
            print(f"{label} Images: {size}, Valid px: 0/{total_px} (Masked: 100.0%)")
            return {'status': 'C2'}

        cloud_pct = 100.0 * (1.0 - float(valid_px) / float(total_px))
        mean_val = band.reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=aoi,
            scale=scale,
            maxPixels=1e9
        ).get(sel_band).getInfo()

        if mean_val is None or (isinstance(mean_val, float) and (math.isnan(mean_val) or math.isinf(mean_val))):
            print(f"{label} Mean invalid.")
            return {'status': 'C3'}

        print(f"{label} Images: {size}, Valid px: {valid_px}/{total_px} (Masked: {cloud_pct:.1f}%), Mean NTL[{sel_band}]: {float(mean_val):.3f}")
        return {'status': 'OK', 'mean': float(mean_val)}
    except Exception as e:
        print(f"{label} Error.")
        return {'status': 'D'}

# 2. Execute and compare
s6 = get_day_stats(dates['Jan06'], 'Jan06')
if s6.get('status') != 'OK':
    print(s6['status'])
    sys.exit(0)

